      </div>
      <div class="reg-link reg-container" v-if="showRegister">
        <button @click="registerUser">Register</button>
      </div>
      <div class="cta-container" v-else>
        <button class="login-button" @click="loginUser"></button>
        <a class="register-link" href="#" @click.prevent="showRegister = true; showReg()">Click here to register</a>
      </div>
    </div>
    <div v-else="closeModal">
      <p>Welcome, {{ store.user.name }}!</p>
      <button @click="logoutUser">Logout</button>
    </div>
  </div>
</template>

<script>
import { initializeApp } from "firebase/app";
import { 
  getAuth, 
  createUserWithEmailAndPassword, 
  signInWithEmailAndPassword, 
  setPersistence,  
  browserLocalPersistence,
  signOut,
  onAuthStateChanged
} from "firebase/auth";
import { getDatabase, ref, child, get, set } from "firebase/database";
import Config from '../config';
import { store } from '../scripts/store';
import gsap from "gsap";
import { onMounted, nextTick } from "vue";

export default {
  data() {
    return {
      message: 'Secure Channel Access',
      email: '',
      password: '',
      name: '',
      showRegister: false,
      errorMessage: ''
    }
  },
  created() {
    // Initialize Firebase
    this.app = initializeApp(Config.firebaseConfig);
    this.auth = getAuth(this.app);
    var loginTl = gsap.timeline();

    onMounted(async () => {
      await nextTick(); // Ensures Vue has finished rendering before GSAP runs
      var loginDiv = document.querySelectorAll('.big-container div');
      var loginContent = document.querySelectorAll('.big-container svg path:not(.outline)');

      loginTl.set("#maskRect", {
          width: "0%",
      });
      loginTl.set(loginContent, {
          opacity: 0,
      });
      loginTl.set(loginDiv, {
          opacity: 0,
      });
      loginTl.to("#maskRect", { 
          width: "100%", 
          duration: 1, 
          ease: "linear",
          delay: 0.5,
      });
      loginTl.to(loginDiv, {
          opacity: 1,
          duration: 0.3,
          ease: "power1.inOut",
      })
      loginTl.to(loginContent, {
          opacity: 1,
          duration: 0.3,
          ease: "power1.inOut",
      })
    });
    // Check authentication state
    onAuthStateChanged(this.auth, (user) => {
      if (user) {
        store.login({ uid: user.uid });
        this.fetchUserName(user.uid);
        this.closeModal();
      } else {
        store.logout();
      }
    });
  },
  methods: {
    setCookie(name, value, daysToExpire) {
      const date = new Date();
      date.setTime(date.getTime() + (daysToExpire * 24 * 60 * 60 * 1000));
      const expires = `expires=${date.toUTCString()}`;
      document.cookie = `${name}=${value}; ${expires}; path=/`;
    },
    displayMessage(props) {
      console.log(props);
    },
    registerUser() {
      createUserWithEmailAndPassword(this.auth, this.email, this.password)
        .then((userCredential) => {
          const user = userCredential.user;
          const profileData = {
            name: this.name,
            email: this.email,
            isAdmin: false,
            last_login: Date.now()
          };
          const db = getDatabase();
          set(ref(db, 'profiles/' + user.uid), profileData);
          store.login({ uid: user.uid, name: this.name, isAdmin: user.isAdmin });
          this.errorMessage = '';
        })
        .catch((error) => {
          this.errorMessage = error.message;
          this.errorDashes();
        });
    },
    loginUser() {
      setPersistence(this.auth, browserLocalPersistence)
        .then(() => {
          return signInWithEmailAndPassword(this.auth, this.email, this.password);
        })
        .then((userCredential) => {
          store.login({ uid: userCredential.user.uid });
          this.fetchUserName(userCredential.user.uid);
          this.errorMessage = '';
          localStorage.setItem('motw-uid',userCredential.user.uid);
          localStorage.setItem('motw-user',JSON.stringify(userCredential.user));
        })
        .catch((error) => {
          this.errorMessage = error.message;
          this.errorDashes(true);
        });
    },
    logoutUser() {
      signOut(this.auth).then(() => {
        store.logout();
        localStorage.removeItem('motw-uid');
        localStorage.removeItem('motw-user');
      }).catch((error) => {
        console.error(error);
      });
    },
    fetchUserName(uid) {
      console.log(128, 'Fetch username');
      const db = getDatabase();
      const userRef = ref(db, 'profiles/' + uid);
      get(userRef).then((snapshot) => {
        if (snapshot.exists()) {
          store.user.name = snapshot.val().name;
          store.isAdmin = snapshot.val().isAdmin;
        } else {
          console.log("No user data available");
        }
      }).catch((error) => {
        console.error(error);
      });
    },
    showReg() {
      var regTl = gsap.timeline();
      var regCont = document.querySelector('.reg-container');
      var loginDashes = document.querySelectorAll('.big-container .login-dash');

      regTl.to(loginDashes, {
        opacity: 0,
        duration: 0.1,
        stagger: 0.1,
        onComplete: () => {
          regTl.to('.reg-container', {
            opacity: 1,
            duration: 0.4,
            ease: 'linear'
          })
        }
      })
    },
    errorDashes(both) {
      var regErrorTl = gsap.timeline();
      var regErrorTlBoth = gsap.timeline();
      var loginDashes = document.querySelectorAll('.big-container .login-dash');
      var loginErrorDashes = document.querySelectorAll('.big-container .error-dash');

      if(both){
        regErrorTlBoth.to(loginDashes, {
          fill: '#DE1920',
          duration: 0.1,
          stagger: 0.1,
        })
      }
      regErrorTl.to(loginErrorDashes, {
        fill: '#DE1920',
        duration: 0.1,
        stagger: 0.1,
      })
    }
  },
  computed: {
    store() {
      return store;
    }
  }
}
</script>

